import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { FigurePipe } from '../../core/locale';
import { Component, computed, effect, inject, signal, untracked, viewChild } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim, ClaimShare, Claims, PersonGrade, bound, byListed, claimDue, counts, deferred, dueFixed, gradeOn, isOpen, overdue, plusDays, roundingOf, statusOn, sumAmounts, tagsOf } from '../claims/claims';
import { Period, Periods, periodOn } from '../periods/periods';
import { Rate, Rates, capped, changeFrom, excessOver, rateOn, scoreOf, sharedPartOf, sumDues, sumShared, trimmedSumDues } from '../rates/rates';
import { ClassicPeriodSummary, ClassicSummary, GradeSummary, PeriodSummary, StatusSummary, Summary, VoidReasonSummary } from '../summary/summary';
import { VoidReasons } from '../../core/void-reasons';
import { Header } from '../header/header';
import { CrewTotal, Crews } from '../crews/crews';
import { Pools } from '../pools/pools';
import { PersonPlans } from '../plans/plans';
import { Plans } from '../../core/plans';
import { COLUMNS, ColumnKey, UserColumns } from '../../core/columns';

interface Person {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the person was read. */
  grade: string;
  /** Every grade of the person, each from its from-date; the first one given from the beginning of time. */
  grades: PersonGrade[];
  /** The person's own terms in force on the sheet's today, in whole days; null when they have none. */
  terms: number | null;
  /** The person's own terms from the beginning of time, in whole days; null when they have none. */
  undatedTerms: number | null;
  /** The person's contact, trimmed and lower-cased; null when they have none. */
  contact: string | null;
  /** The person's tags: trimmed, lower-cased, without repeats, sorted and joined by commas; null when they have none. */
  tags: string | null;
  /** Raised on each save; the editor sends back the one it loaded. */
  version: number;
  /** How many statements the person has had. */
  statementCount: number;
  /** The due-total recorded by the last statement; null with none. */
  statedTotal: string | null;
  /** The date the last statement was taken as of (yyyy-mm-dd): the sheet's today then, or an earlier date given; null with none. */
  statementDate: string | null;
  /** Whether the person has a retirement date: they count as retired at once, whatever the date. */
  retired: boolean;
  /** The date the person is retired from (yyyy-mm-dd); null while not retired. */
  retiredFrom: string | null;
  /** The person's past retirements by from-date, each from its from-date to the day they were unretired. */
  retirements: { from: string; to: string }[];
  /** Whether the person has any hold. */
  held: boolean;
  /** The person's holds by from-date: their OPEN and PENDING claims dated within one, unless a statement binds them,
   *  count in no live total; their SETTLED ones still do. */
  holds: PersonHold[];
  /** The ids of the other people on the sheet the person has named as their patrons. */
  patronIds: number[];
  /** Each patron's share of 100.00, in the order of {@link patronIds}. */
  patronShares: string[];
  /** Whether the signed-in user watches the person. */
  watched: boolean;
  /** The other names the person goes by, sorted as names are compared. */
  aliases: string[];
  /** Whether the person's name or an alias is used on another sheet of the sheet's tree: every edit of them is
   *  refused until a rename clears it. */
  clashing: boolean;
  /** The sheet the person was transferred from; null for anyone else. */
  origin: string | null;
  /** One line per SNAPSHOT written for the person, oldest first: the day being left, then the due-total. */
  snapshotLines: string[];
  /** One line per statement still standing, oldest first by its date: the date, then the due-total. */
  statementLines: string[];
  /** The reason of the person's flag while the sheet's today is on or before its until-date; null otherwise. While
   *  it is in force only a steward may open a claim of theirs. */
  flag: string | null;
  /** The user who may approve or reject the person's PENDING claims as a steward may; null when none. */
  approver: string | null;
}

/** A hold of a person from its from-date to its to-date (yyyy-mm-dd), both inclusive; to null: it does not end. */
interface PersonHold {
  from: string;
  to: string | null;
}

/**
 * The figures of a sheet's descendants added up: their people, due-totals and overdue-totals; per grade, the due-totals
 * of the people on it not retired; and per status, how many claims have it.
 */
interface DescendantFigures {
  people: number;
  dueTotal: string;
  overdueTotal: string;
  gradeDueTotals: Record<string, string>;
  statusCounts: Record<string, number>;
  members: TreeMember[];
  overdueCount: number;
}

/** A person of a sheet as that sheet shows them: due-total, overdue-total, and name and aliases as names are compared. */
interface TreeMember {
  dueTotal: string;
  overdueTotal: string;
  names: string[];
}

/** How many people the members are, those whose names or aliases match (as names are compared) being one. */
function distinctPeople(members: TreeMember[]): number {
  const parent = members.map((_, i) => i);
  const top = (i: number): number => (parent[i] === i ? i : top(parent[i]));
  const firstWith = new Map<string, number>();
  let count = members.length;
  members.forEach((m, i) => {
    for (const name of m.names) {
      const other = firstWith.get(name);
      if (other === undefined) {
        firstWith.set(name, i);
        continue;
      }
      const a = top(i);
      const b = top(other);
      if (a !== b) {
        parent[a] = b;
        count--;
      }
    }
  });
  return count;
}

/** A name as names are compared: trimmed, ignoring case. */
function nameKey(name: string): string {
  return name.trim().toLowerCase();
}

type SortKey = 'added' | 'name' | 'grade' | 'due-total';

function compareKeys(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

const NO_DESCENDANTS: DescendantFigures = {
  people: 0,
  dueTotal: '0.00',
            [checked]="columns.shows(c.key)"
            (change)="chooseColumn(c.key, checked($event))"
          />
          <label [for]="'column-' + c.key">{{ c.label }}</label>
        }
        @if (columnsError(); as message) {
          <p role="alert" data-testid="columns-error">{{ message }}</p>
        }
      </fieldset>
      <table>
        <thead>
          <tr>
            <th scope="col"><span class="visually-hidden">Select</span></th>
            <th scope="col">Name</th><th scope="col">Grade</th>@if (columns.shows('terms')) { <th scope="col">Terms</th> }@if (columns.shows('contact')) { <th scope="col">Contact</th> }<th scope="col">Tags</th>@if (columns.shows('aliases')) { <th scope="col">Aliases</th> }<th scope="col">From sheet</th><th scope="col">Clashing</th>@if (columns.shows('claimed')) { <th scope="col">Claimed</th> }@if (columns.shows('due-total')) { <th scope="col">Due</th> }<th scope="col">Settled</th><th scope="col">Open</th><th scope="col">Score</th><th scope="col">Band</th>
            @for (per of periods(); track per.id) {
              <th scope="col">Due in {{ per.name }}</th>
              <th scope="col">Carried into {{ per.name }}</th>
            }
            @if (columns.shows('statement-count')) { <th scope="col">Statements</th> }@if (columns.shows('stated-total')) { <th scope="col">Last stated</th> }@if (columns.shows('statement-date')) { <th scope="col">Stated on</th> }
            @if (columns.shows('retired')) { <th scope="col">Retired</th> }<th scope="col">Retired from</th><th scope="col">Past retirements</th><th scope="col">Snapshots</th><th scope="col">Statement lines</th>@if (columns.shows('hold')) { <th scope="col">On hold</th> }<th scope="col">Active</th>
            @if (columns.shows('overdue-count')) { <th scope="col">Overdue</th> }@if (columns.shows('overdue-total')) { <th scope="col">Overdue total</th> }
            <th scope="col">Due aged 0–30</th><th scope="col">Due aged 31–60</th><th scope="col">Due aged 61+</th>
            @if (columns.shows('patrons')) { <th scope="col">Patrons</th> }@if (columns.shows('backing')) { <th scope="col">Backing</th> }@if (columns.shows('excess')) { <th scope="col">Excess</th> }<th scope="col">Cut total</th><th scope="col">Watched</th>
            <th scope="col"><span class="visually-hidden">Actions</span></th><th scope="col">Claims</th>
          </tr>
        </thead>
        <tbody>
          @for (p of sorted(); track p.id) {
            <tr [attr.data-testid]="'person-row-' + p.id">
              <td>
                <input
                  type="checkbox"
                  data-testid="person-select"
                  [attr.aria-label]="'Select ' + p.name"
                  [checked]="selectedPeople().has(p.id)"
                  (change)="selectPerson(p.id, checked($event))"
                />
              </td>
              <td data-testid="person-name">{{ shownName(p) | fig }}</td>
              <td data-testid="person-grade">{{ gradeOf(p) | fig }}</td>
              @if (columns.shows('terms')) {
                <td data-testid="person-terms">{{ p.terms ?? '' | fig }}</td>
              }
              @if (columns.shows('contact')) {
                <td data-testid="person-contact">{{ p.contact ?? '' | fig }}</td>
              }
              <td data-testid="person-tags">{{ personTagsOf(p).join(', ') | fig }}</td>
              @if (columns.shows('aliases')) {
                <td data-testid="person-aliases">{{ p.aliases.join(', ') | fig }}</td>
              }
              <td data-testid="person-origin">{{ p.origin ?? '' | fig }}</td>
              <td data-testid="person-clashing">{{ p.clashing ? 'yes' : 'no' | fig }}</td>
              @if (columns.shows('claimed')) {
                <td data-testid="person-claimed">{{ claimedBy(p.id) | fig }}</td>
              }
              @if (columns.shows('due-total')) {
                <td data-testid="person-due-total">{{ dueTotalOf(p) | fig }}</td>
              }
              <td data-testid="person-settled-total">{{ settledTotalOf(p) | fig }}</td>
              <td data-testid="person-open-total">{{ openTotalOf(p) | fig }}</td>
              <td data-testid="person-score">{{ personScoreOf(p) }}</td>
              <td data-testid="person-band">{{ personBandOf(p) }}</td>
              @for (per of periods(); track per.id) {
                <td [attr.data-testid]="'person-period-' + per.name + '-due-total'">{{ periodDueTotalOf(p, per) | fig }}</td>
                <td [attr.data-testid]="'person-period-' + per.name + '-carried'">{{ carriedOf(p, per) | fig }}</td>
              }
              @if (columns.shows('statement-count')) {
                <td data-testid="person-statement-count">{{ p.statementCount | fig }}</td>
              }
              @if (columns.shows('stated-total')) {
                <td data-testid="person-stated-total">{{ p.statedTotal ?? '' | fig }}</td>
              }
              @if (columns.shows('statement-date')) {
                <td data-testid="person-statement-date">{{ p.statementDate ?? '' | fig }}</td>
              }
              @if (columns.shows('retired')) {
                <td data-testid="person-retired">{{ p.retired ? 'yes' : 'no' | fig }}</td>
              }
              <td data-testid="person-retired-from">{{ p.retiredFrom ?? '' | fig }}</td>
              <td>
                @for (r of p.retirements; track $index) {
                  <div data-testid="person-retirement-line">{{ r.from }} to {{ r.to }}</div>
                }
              </td>
              <td>
                @for (line of p.snapshotLines; track $index) {
                  <div data-testid="person-snapshot-line">{{ line | fig }}</div>
                }
              </td>
              <td>
                @for (line of p.statementLines; track $index) {
                  <div data-testid="person-statement-line-line">{{ line | fig }}</div>
                }
              </td>
              @if (columns.shows('hold')) {
                <td data-testid="person-hold">{{ p.held ? 'yes' : 'no' | fig }}</td>
              }
              <td data-testid="person-active">{{ isActive(p) ? 'yes' : 'no' | fig }}</td>
              @if (columns.shows('overdue-count')) {
                <td data-testid="person-overdue-count">{{ overdueOf(p).length | fig }}</td>
              }

