   *  it is in force only a steward may open a claim of theirs. */
  flag: string | null;
  /** The user who may approve or reject the person's PENDING claims as a steward may; null when none. */
  approver: string | null;
}

/** A hold of a person from its from-date to its to-date (yyyy-mm-dd), both inclusive; to null: it does not end. */
interface PersonHold {
  from: string;
  to: string | null;
}

/**
 * The figures of a sheet's descendants added up: their people, due-totals and overdue-totals; per grade, the due-totals
 * of the people on it not retired; and per status, how many claims have it.
 */
interface DescendantFigures {
  people: number;
  dueTotal: string;
  overdueTotal: string;
  gradeDueTotals: Record<string, string>;
  statusCounts: Record<string, number>;
  members: TreeMember[];
  overdueCount: number;
}

/** A person of a sheet as that sheet shows them: due-total, overdue-total, and name and aliases as names are compared. */
interface TreeMember {
  dueTotal: string;
  overdueTotal: string;
  names: string[];
}

/** How many people the members are, those whose names or aliases match (as names are compared) being one. */
function distinctPeople(members: TreeMember[]): number {
  const parent = members.map((_, i) => i);
  const top = (i: number): number => (parent[i] === i ? i : top(parent[i]));
  const firstWith = new Map<string, number>();
  let count = members.length;
  members.forEach((m, i) => {
    for (const name of m.names) {
      const other = firstWith.get(name);
      if (other === undefined) {
        firstWith.set(name, i);
        continue;
      }
      const a = top(i);
      const b = top(other);
      if (a !== b) {
        parent[a] = b;
        count--;
      }
    }
  });
  return count;
}

/** A name as names are compared: trimmed, ignoring case. */
function nameKey(name: string): string {
  return name.trim().toLowerCase();
}

type SortKey = 'added' | 'name' | 'grade' | 'due-total';

function compareKeys(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

